<?php
require dirname(__DIR__,3).'/vendor/autoload.php';$app=require dirname(__DIR__,3).'/bootstrap/app.php';$app->make(Illuminate\Contracts\Console\Kernel::class)->bootstrap();
$service=app(App\Services\UserTaskMonitoringService::class);$user=App\Models\User::where('system_role','user')->where('account_status','active')->where('must_change_password',false)->get()->first(fn($u)=>$service->getMonitoredProjects($u)->isNotEmpty());if(!$user)throw new Exception('No eligible manager');$kernel=app(Illuminate\Contracts\Http\Kernel::class);
foreach(['/tasks/my','/tasks/my?view=managed','/team-monitor','/tasks/my?view=managed&tab=team&project_id=7'] as $i=>$uri){$app['auth']->forgetGuards();$app['auth']->guard()->setUser($user);$r=Illuminate\Http\Request::create('http://127.0.0.1:8000'.$uri,'GET');$r->setUserResolver(fn()=>$user);$app->instance('request',$r);$response=$kernel->handle($r);if($i===3){if(!$response->isRedirect()||!str_contains($response->headers->get('Location'),'/team-monitor?project_id=7'))throw new Exception('legacy redirect failed');}else{if($response->getStatusCode()!==200)throw new Exception('Page failed: '.$uri);$html=$response->getContent();if($i<2 && str_contains($html,"tab' => 'team'"))throw new Exception('Embedded team navigation');if($i===2 && str_contains($html,'personal-view-switch'))throw new Exception('Task scope switch on team page');$html=preg_replace('#(href|src)="http://127.0.0.1:8000/(css|js)/#','$1="file:///'.str_replace('\\','/',dirname(__DIR__,3)).'/public/$2/',$html);file_put_contents(__DIR__.'/personal-'.['assigned','managed','team'][$i].'.html',$html);}echo 'PASS '.$uri.PHP_EOL;}
